<script setup lang="ts">
import {computed} from 'vue'
import {ChevronRight,Info,Plane} from 'lucide-vue-next'
import type {Dashboard} from '../../types'

const props=defineProps<{capital:Dashboard['capital'];routes:Dashboard['routes'];availableSlots:number}>()
const total=computed(()=>Number(props.capital.total)||0)
const available=computed(()=>Number(props.capital.available)||0)
const inFlight=computed(()=>Number(props.capital.in_flight)||0)
const readyCapital=computed(()=>Number(props.capital.ready_to_return)||0)
const deployed=computed(()=>inFlight.value+readyCapital.value)
const deployedPercent=computed(()=>total.value?Math.min(deployed.value/total.value*100,100):0)
const availablePercent=computed(()=>Math.max(100-deployedPercent.value,0))
const readyRoutes=computed(()=>props.routes.filter(route=>route.visual_state==='READY'))
const readyQuantity=computed(()=>readyRoutes.value.reduce((value,route)=>value+Number(route.remaining_quantity||0),0))
const sum=(states:string[])=>props.routes.filter(route=>states.includes(route.visual_state)).reduce((value,route)=>value+Number(route.capital_amount||0),0)
const cruising=computed(()=>sum(['FLYING','PARKED_NEGATIVE','WAITING_QUOTE']))
const approaching=computed(()=>sum(['APPROACHING','ARRIVED_LOCKED']))
const landed=computed(()=>sum(['READY']))
const compositionTotal=computed(()=>cruising.value+approaching.value+landed.value)
const cruisingPercent=computed(()=>compositionTotal.value?cruising.value/compositionTotal.value*100:0)
const approachingPercent=computed(()=>compositionTotal.value?approaching.value/compositionTotal.value*100:0)
const landedPercent=computed(()=>compositionTotal.value?landed.value/compositionTotal.value*100:0)
const activeStateCount=computed(()=>[cruising.value,approaching.value,landed.value].filter(value=>value>0).length)
const currency=(value:number)=>new Intl.NumberFormat('zh-CN',{style:'currency',currency:'CNY',maximumFractionDigits:0}).format(value)
const number=(value:number)=>new Intl.NumberFormat('zh-CN',{maximumFractionDigits:0}).format(value)
const whole=(value:number)=>`${Math.round(value)}%`
const inFlightPercent=computed(()=>total.value?inFlight.value/total.value*100:0)
const readyPercent=computed(()=>total.value?readyCapital.value/total.value*100:0)
const allocationRing=computed(()=>{const inFlightEnd=inFlightPercent.value,readyEnd=inFlightEnd+readyPercent.value;return `conic-gradient(#2f72df 0 ${inFlightEnd}%,#1aa373 ${inFlightEnd}% ${readyEnd}%,#e2e8ef ${readyEnd}% 100%)`})
const compositionRing=computed(()=>{const cruisingEnd=cruisingPercent.value,approachingEnd=cruisingEnd+approachingPercent.value;return compositionTotal.value?`conic-gradient(#2f6fd6 0 ${cruisingEnd}%,#e39b2d ${cruisingEnd}% ${approachingEnd}%,#1e9e63 ${approachingEnd}% 100%)`:'#e6ebf2'})
</script>

<template>
  <section class="capital-status-panel">
    <header><div><small>CAPITAL DISPATCH</small><h2>资金池态势</h2></div><Info :size="15"><title>展示资金调度比例及在航资金状态构成</title></Info></header>
    <div class="primary-ring" :style="{background:allocationRing}">
      <div><strong>{{currency(total)}}</strong><span>总资金</span></div>
    </div>
    <div class="allocation-legend">
      <article><i class="blue"></i><div><span>在航资金</span><small>{{routes.length-readyRoutes.length}} 航次</small></div><strong>{{currency(inFlight)}}</strong><em>{{whole(inFlightPercent)}}</em></article>
      <article><i class="green"></i><div><span>待返航资金</span><small>{{readyRoutes.length}} 航次</small></div><strong>{{currency(readyCapital)}}</strong><em>{{whole(readyPercent)}}</em></article>
      <article><i class="gray"></i><div><span>可调度资金</span><small>{{availableSlots}} 舱位</small></div><strong>{{currency(available)}}</strong><em>{{whole(availablePercent)}}</em></article>
    </div>
    <div class="composition">
      <div class="composition-heading"><h3>航次资金构成</h3><strong>{{currency(compositionTotal)}}</strong></div>
      <div class="composition-body">
        <div class="composition-ring" :style="{background:compositionRing}"><div><strong>{{activeStateCount||'—'}}</strong><span>种运行状态</span></div></div>
        <div class="composition-legend">
          <article><i class="blue"></i><span>巡航</span><strong>{{currency(cruising)}}</strong><em>{{whole(cruisingPercent)}}</em></article>
          <article><i class="amber"></i><span>近进</span><strong>{{currency(approaching)}}</strong><em>{{whole(approachingPercent)}}</em></article>
          <article><i class="green"></i><span>已着陆</span><strong>{{currency(landed)}}</strong><em>{{whole(landedPercent)}}</em></article>
        </div>
      </div>
    </div>
    <div class="ready-section">
      <header><div><h3>待返航</h3></div></header>
      <div v-if="readyRoutes.length" class="ready-list">
        <div v-for="route in readyRoutes" :key="route.id" class="ready-ticket">
          <span class="ready-icon"><Plane :size="13"/></span>
          <div><b>{{route.voyage_no}}</b><small>{{route.name}}｜可售金额：{{currency(Number(route.monitor_price||0)*route.remaining_quantity)}}</small></div>
          <strong>{{number(route.remaining_quantity)}}<small>份</small></strong><ChevronRight :size="17" class="ready-arrow"/>
        </div>
      </div>
    </div>
  </section>
</template>

